<?php

namespace App\Http\Controllers;

use Illuminate\Http\JsonResponse;
use Illuminate\Support\Facades\URL;
use Symfony\Component\HttpFoundation\BinaryFileResponse;

/**
 * The database documentation page (schema, routes with their auth layer,
 * code findings), generated by scripts/erd/build.sh into public/erd.html.
 *
 * The Admin → Docs button opens it through a short-lived signed link; the
 * file itself is also reachable directly at /erd.html.
 */
class ErdController extends Controller
{
    /** GET /api/v1/admin/erd-link — admin only (route middleware). */
    public function link(): JsonResponse
    {
        if (! is_file(self::file())) {
            return response()->json(['success' => false, 'message' => 'لم تُولَّد صفحة التوثيق بعد. شغّل scripts/erd/build.sh.'], 404);
        }

        return response()->json([
            'success' => true,
            'url' => URL::temporarySignedRoute('erd.show', now()->addMinutes(30)),
            'generated_at' => date('Y-m-d H:i', filemtime(self::file())),
        ]);
    }

    /** GET /internal/erd — only through a valid signed link (route middleware). */
    public function show(): BinaryFileResponse
    {
        abort_unless(is_file(self::file()), 404);

        return response()->file(self::file(), [
            'Content-Type' => 'text/html; charset=UTF-8',
            'Cache-Control' => 'no-store, private',
            'X-Robots-Tag' => 'noindex, nofollow',
            'Referrer-Policy' => 'no-referrer',
        ]);
    }

    public static function file(): string
    {
        return public_path('erd.html');
    }
}
